  v_once    integer;
  v_eklenen integer;
  v_sonra   integer;
begin
  select id into v_admin from public.profiles where role = 'admin' order by id limit 1;
  if v_admin is null then
    raise exception 'sözlük yükleme: yönetici profil bulunamadı';
  end if;

  select count(*) into v_once from public.okuma_sozluk_girdileri;

  insert into public.okuma_sozluk_girdileri
    (id, tur, yazim, anlam, sinif_alt, sinif_ust, kaynak_turu, kazanim_kodu, durum, olusturan_id)
  select g ->> 'id', g ->> 'tur', g ->> 'yazim', g ->> 'anlam',
         (g ->> 'sinif_alt')::smallint, (g ->> 'sinif_ust')::smallint,
         g ->> 'kaynak_turu', null, 'taslak', v_admin
    from jsonb_array_elements(v_p -> 'girdiler') g
   where not exists (select 1 from public.okuma_sozluk_girdileri x where x.id = g ->> 'id');
  get diagnostics v_eklenen = row_count;

  insert into public.okuma_sozluk_yuvalari (tur, ad)
  select y ->> 'tur', y ->> 'ad'
    from jsonb_array_elements(v_p -> 'yuvalar') y
  on conflict (tur, ad) do nothing;

  insert into public.okuma_sozluk_adaylari (yuva_tur, yuva_ad, girdi_id, sira)
  select y ->> 'tur', y ->> 'ad', a ->> 'girdi', (a ->> 'sira')::smallint
    from jsonb_array_elements(v_p -> 'yuvalar') y
    cross join lateral jsonb_array_elements(y -> 'adaylar') a
   where exists (select 1 from public.okuma_sozluk_girdileri x where x.id = a ->> 'girdi')
  on conflict do nothing;

  select count(*) into v_sonra from public.okuma_sozluk_girdileri;
  if v_sonra <> v_once + v_eklenen then
    raise exception 'sözlük yükleme: sayı tutarsız (önce %, eklenen %, sonra %)', v_once, v_eklenen, v_sonra;
  end if;
  raise notice 'sözlük: önce % girdi, eklenen %, atlanan (zaten var) %', v_once, v_eklenen,
    jsonb_array_length(v_p -> 'girdiler') - v_eklenen;
end
$sozluk$;